int direct[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
​
// 记录最大步数
int res = 0;
int m, n;
​
// count 已经走过的步数 lastType 0 起点 1 上升 -1下降
void dfs(int x, int y, vector<vector<int>>& grid, vector<vector<bool>>& visitd, int count, int lastType) {
    res = max(res, count);
    for (int i = 0; i < 4; i++) {
        int nx = x + direct[i][0];
        int ny = y + direct[i][1];
        // 越界 访问过
        if (nx < 0 || ny < 0 || nx >= m || ny >= n || visitd[nx][ny]) {
            continue;
        }
        // 高度相同
        if(grid[nx][ny] == grid[x][y]) {
            continue;
        }
​
        int currentType = grid[nx][ny] > grid[x][y] ? 1 : -1;
        // 不允许连续爬升或下降
        if (lastType != 0 && lastType == currentType) {
            continue;
        }
        // 递归回溯
        visitd[nx][ny] = true;
        dfs(nx, ny, grid ,visitd, count + 1, currentType);
        visitd[nx][ny] = false;
    }
} 
