 * @param {number} x - 当前 x 坐标
 * @param {number} y - 当前 y 坐标
 * @param {Array} visited - 访问记录数组
 * @param {number} count - 已走步数
 * @param {number} lastType - 上升 (1), 下降 (-1), 初始点 (0)
 */
const dfs = (x, y, visited, count, lastType) => {
    res = Math.max(res, count);
​
    for (let [dx, dy] of directions) {
        let nx = x + dx, ny = y + dy;
