package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 方向数组：上、下、左、右
var directions = [][]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
var res, m, n int
​
/**
 * 深度优先搜索 (DFS)
 * @param x 当前 x 坐标
 * @param y 当前 y 坐标
 * @param grid 高度矩阵
 * @param visited 访问记录数组
 * @param count 当前已经走过的步数
 * @param lastType 0-起点 1-上升 -1-下降
 */
func dfs(x, y int, grid [][]int, visited [][]bool, count, lastType int) {
    res = max(res, count)
​
    for _, d := range directions {
        nx, ny := x+d[0], y+d[1]
​
        // 越界或已访问
        if nx < 0 || ny < 0 || nx >= m || ny >= n || visited[nx][ny] {
            continue
        }
        // 高度相同则跳过
        if grid[nx][ny] == grid[x][y] {
            continue
        }
​
        currentType := 1
        if grid[nx][ny] < grid[x][y] {
            currentType = -1
        }
​
        // 不允许连续爬升或下降
        if lastType != 0 && lastType == currentType {
            continue
        }
​
        // 递归回溯
        visited[nx][ny] = true
        dfs(nx, ny, grid, visited, count+1, currentType)
        visited[nx][ny] = false
    }
}
​
/**
 * 读取标准输入
 * @return int 矩阵行数和列数, 以及网格数据
 */
func main() {
    // 读取输入
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    firstLine := strings.Fields(scanner.Text())
    m, _ = strconv.Atoi(firstLine[0])
    n, _ = strconv.Atoi(firstLine[1])
​
    // 读取网格数据
    grid := make([][]int, m)
    for i := 0; i < m; i++ {
        scanner.Scan()
        rowStr := strings.Fields(scanner.Text())
        grid[i] = make([]int, n)
        for j := 0; j < n; j++ {
            grid[i][j], _ = strconv.Atoi(rowStr[j])
        }
    }
​
    // 遍历所有起点
    for i := 0; i < m; i++ {
        for j := 0; j < n; j++ {
            visited := make([][]bool, m)
            for k := range visited {
                visited[k] = make([]bool, n)
            }
            visited[i][j] = true
            dfs(i, j, grid, visited, 0, 0)
        }
    }
​
    // 输出最大步数
    fmt.Println(res)
}
​
/**
 * 返回两个整数中的最大值
 */
func max(a, b int) int {
    if a > b {
        return a
    }
    return b
}
